"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const EventEmitter = require("events");
const functions = require("../functions/jsondb.js");

const ENCRYPTION_PREFIX = "croxydb:v1:";

/**
 * JSON file adapter for CroxyDB.
 * @module adapters/jsondb
 */

/**
 * @typedef {Object} JsonDBOptions
 * @property {string} dbName JSON file name without extension.
 * @property {string} dbFolder Folder where the JSON file is stored.
 * @property {boolean} [readable=false] Pretty-print JSON output.
 * @property {string} [seperator="."] Nested-key separator.
 * @property {string|null} [encryptionKey] AES-256-GCM encryption key.
 * @property {Object<string, number>} [ttl] Shared TTL metadata.
 */

function clone(value) {
  if (value === undefined) return undefined;
  return JSON.parse(JSON.stringify(value));
}

function createKey(secret) {
  return crypto.createHash("sha256").update(String(secret)).digest();
}

/**
 * Stores data in a local JSON file.
 * @class
 * @extends EventEmitter
 */
class JsonDB extends EventEmitter {
  /**
   * Creates a JSON adapter.
   * @param {JsonDBOptions} options Adapter options.
   */
	constructor(options) {
    super();
		this.dbName = options["dbName"];
	    this.dbFolder = options["dbFolder"];
	    this.noBlankData = options["noBlankData"] ? (typeof options["noBlankData"] === "boolean" ? options["noBlankData"] : false) : false;
	    this.readable = options["readable"] ? (typeof options["readable"] === "boolean" ? true : false) : false;
      this.seperator = options["seperator"]
      this.ttl = options["ttl"] || {};
      this.encryptionKey = options["encryptionKey"] || null;
      this.filePath = path.join(".", this.dbFolder, `${this.dbName}.json`);
      this.ttlPath = path.join(".", this.dbFolder, `${this.dbName}.ttl.json`);
      this.message = require("../language/en.json");

	    functions.fetchFiles(this.dbFolder, this.dbName);
      this.ttl = this.readTTL();
	}

  /**
   * Encrypts serialized JSON text when encryption is enabled.
   * @param {string} text Plain text.
   * @returns {string}
   */
  encrypt(text) {
    if (!this.encryptionKey) return text;
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv("aes-256-gcm", createKey(this.encryptionKey), iv);
    const encrypted = Buffer.concat([cipher.update(text, "utf8"), cipher.final()]);
    return `${ENCRYPTION_PREFIX}${iv.toString("base64")}:${cipher.getAuthTag().toString("base64")}:${encrypted.toString("base64")}`;
  }

  /**
   * Decrypts serialized JSON text when it uses the CroxyDB encryption prefix.
   * @param {string} text Stored text.
   * @returns {string}
   */
  decrypt(text) {
    if (!text || !text.startsWith(ENCRYPTION_PREFIX)) return text || "{}";
    if (!this.encryptionKey) {
      throw new TypeError("This database file is encrypted. Call setEncryptionKey(key) before reading it.");
    }
    const payload = text.slice(ENCRYPTION_PREFIX.length).split(":");
    const decipher = crypto.createDecipheriv("aes-256-gcm", createKey(this.encryptionKey), Buffer.from(payload[0], "base64"));
    decipher.setAuthTag(Buffer.from(payload[1], "base64"));
    return Buffer.concat([decipher.update(Buffer.from(payload[2], "base64")), decipher.final()]).toString("utf8");
  }

  /**
   * Reads and parses the JSON database file.
   * @returns {Object}
   */
  readContent() {
    functions.fetchFiles(this.dbFolder, this.dbName);
    const raw = fs.readFileSync(this.filePath, "utf8");
    const parsed = JSON.parse(this.decrypt(raw));
    return parsed && typeof parsed === "object" ? parsed : {};
  }

  /**
   * Reads TTL metadata from disk.
   * @returns {Object<string, number>}
   */
  readTTL() {
    try {
      if (!fs.existsSync(this.ttlPath)) return this.ttl || {};
      return JSON.parse(this.decrypt(fs.readFileSync(this.ttlPath, "utf8"))) || {};
    } catch (err) {
      return {};
    }
  }

  /**
   * Writes TTL metadata to disk.
   * @returns {void}
   */
  writeTTL() {
    fs.writeFileSync(this.ttlPath, this.encrypt(JSON.stringify(this.ttl || {})));
  }

  /**
   * Atomically writes JSON content using temp file plus rename.
   * @param {Object} content Database content.
   * @returns {void}
   */
  writeContent(content) {
    const json = this.readable ? JSON.stringify(content, null, 2) : JSON.stringify(content);
    const tempPath = `${this.filePath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tempPath, this.encrypt(json));
    fs.renameSync(tempPath, this.filePath);
  }

  /**
   * Removes expired keys from content.
   * @param {Object} content Database content.
   * @returns {void}
   */
  purgeExpired(content) {
    const now = Date.now();
    let changed = false;
    Object.keys(this.ttl).forEach((key) => {
      if (this.ttl[key] && this.ttl[key] <= now) {
        functions.remove(content, key, this.seperator);
        functions.removeEmptyData(content);
        delete this.ttl[key];
        changed = true;
        this.emit("expire", key);
        this.emit("delete", key);
      }
    });
    if (changed) {
      this.writeTTL();
      this.writeContent(content);
    }
  }

  /**
   * Sets or removes TTL metadata for a key.
   * @param {string} db Database key.
   * @param {number|Date} [ttl] TTL value.
   * @returns {void}
   */
  setTTL(db, ttl) {
    if (typeof ttl === "number" && ttl > 0) {
      this.ttl[db] = Date.now() + ttl;
    } else if (ttl instanceof Date) {
      this.ttl[db] = ttl.getTime();
    } else {
      delete this.ttl[db];
    }
    this.writeTTL();
  }

	/**
   * Stores a value.
   * @param {string} db Database key.
   * @param {*} data Value to store.
   * @param {{ttl?: number|Date}} [options={}] Set options.
   * @returns {*}
   */
	set(db, data, options = {}) {
    functions.fetchFiles(this.dbFolder, this.dbName);

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var content = this.readContent();
    this.purgeExpired(content);
    functions.set(db, clone(data), content, this.seperator);
    this.setTTL(db, options.ttl);

    this.writeContent(content);
    this.emit("set", db, clone(data));
    return this.get(db);
    
  }

  /**
   * Gets a value.
   * @param {string} db Database key.
   * @returns {*|undefined}
   */
  get(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();
    this.purgeExpired(content);

    try {
      return clone(functions.get(content, this.seperator, ...db.split(this.seperator)));
    } catch(err) {
      return undefined;
    }

  }

  /**
   * Alias of {@link JsonDB#get}.
   * @param {string} db Database key.
   * @returns {*|undefined}
   */
  fetch(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();
    this.purgeExpired(content);

    try {
      return clone(functions.get(content, this.seperator, ...db.split(this.seperator)));
    } catch(err) {
      return undefined;
    }

  }

  /**
   * Checks whether a key exists.
   * @param {string} db Database key.
   * @returns {boolean}
   */
  has(db) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();
    this.purgeExpired(content);

    try {
      return functions.has(content, this.seperator, ...db.split(this.seperator));
    } catch(err) {
      return false;
    }

  }

  /**
   * Deletes a key and removes empty parent objects.
   * @param {string} db Database key.
   * @returns {boolean}
   */
  delete(db) {
    functions.fetchFiles(this.dbFolder, this.dbName);

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    var content = this.readContent();
    this.purgeExpired(content);

    if(!functions.has(content, this.seperator, ...db.split(this.seperator))) {
      return false;
    }

    functions.remove(content, db, this.seperator);
    delete this.ttl[db];

    functions.removeEmptyData(content);
    
    this.writeContent(content);
    this.emit("delete", db);

    return true;
  }

  /**
   * Adds a number.
   * @param {string} db Database key.
   * @param {number} number Number to add.
   * @returns {number}
   */
  add(db, number) {
    
    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    this.set(db, Number(this.get(db) ? (isNaN(this.get(db)) ? Number(number) : this.get(db)+Number(number)) : Number(number)));
    
    return this.get(db);

  }

  /**
   * Subtracts a number.
   * @param {string} db Database key.
   * @param {number} number Number to subtract.
   * @returns {number}
   */
  subtract(db, number) {
    
    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    this.set(db, (this.get(db) || 0) - Number(number));
    return this.get(db);

  }

  /**
   * Pushes a value into an array.
   * @param {string} db Database key.
   * @param {*} data Value to push.
   * @returns {Array<*>}
   */
  push(db, data) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var arr = [];

    if(this.get(db)) {
      if(typeof this.get(db) !== "object") {
        arr = [];
      } else {
        arr = this.get(db);
      }
    }

    arr.push(data);

    this.set(db, arr);

    return this.get(db);

  }

  /**
   * Removes matching values from an array.
   * @param {string} db Database key.
   * @param {*} data Value to remove.
   * @returns {Array<*>}
   */
  unpush(db, data) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankName"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    var arr = [];

    if(this.get(db)) {
      arr = this.get(db);
    }

    arr = arr.filter((x) => x !== data);

    this.set(db, arr);

    return this.get(db);

  }

  /**
   * Deletes an array item by one-based priority index.
   * @param {string} db Database key.
   * @param {number} number One-based array index.
   * @returns {Array<*>|false}
   */
  delByPriority(db, number) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(isNaN(number)) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(!this.get(db) || this.get(db).length < 1) {
      return false;
    }

    let content = this.get(db);
    let neww = [];

    if (typeof content !== "object") {
      return false;
    }

    for (let a = 0; a < content.length; a++) {
      if (a !== (number-1)) {
        neww.push(content[`${a}`]);
      }
    }

    this.set(db, neww);
    return this.get(db);

  }

  /**
   * Replaces an array item by one-based priority index.
   * @param {string} db Database key.
   * @param {*} data Replacement value.
   * @param {number} number One-based array index.
   * @returns {Array<*>|false}
   */
  setByPriority(db, data, number) {

    if(!db) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(arguments.length < 2) {
      throw new TypeError(this.message["errors"]["blankData"]);
    }

    if(number !== 0 && !number) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(isNaN(number)) {
      throw new TypeError(this.message["errors"]["blankNumber"]);
    }

    if(!this.get(db) || this.get(db).length < 1) {
      return false;
    }

    let content = this.get(db);
    let neww = [];

    if (typeof content !== "object") {
      return false;
    }

    for (let a = 0; a < content.length; a++) {
      let val = content[`${a}`];

      if(a === (number-1)) {
        neww.push(data);
      } else {
        neww.push(val);
      }
    }

    this.set(db, neww);
    return this.get(db);

  }

  /**
   * Returns all database content.
   * @returns {Object}
   */
  all() {
    var content = this.readContent();
    this.purgeExpired(content);

    return clone(content);
  }

  /**
   * Deletes all database content and TTL metadata.
   * @returns {true}
   */
  deleteAll() {

    this.ttl = {};
    this.writeTTL();
    this.writeContent({});
    this.emit("deleteAll");

    return true;

  }

  async setAsync(db, data, options) { return this.set(db, data, options); }
  async getAsync(db) { return this.get(db); }
  async fetchAsync(db) { return this.fetch(db); }
  async hasAsync(db) { return this.has(db); }
  async deleteAsync(db) { return this.delete(db); }
  async addAsync(db, number) { return this.add(db, number); }
  async subtractAsync(db, number) { return this.subtract(db, number); }
  async pushAsync(db, data) { return this.push(db, data); }
  async unpushAsync(db, data) { return this.unpush(db, data); }
  async allAsync() { return this.all(); }
  async deleteAllAsync() { return this.deleteAll(); }

}

module.exports = JsonDB;
